(function(){
'use strict';

const CFF_MERCADO_STATUS_META={
  rumor:{label:'Rumor',icon:'rumor.webp'},
  negociando:{label:'Negociando',icon:'negociando.webp'},
  fechado:{label:'Fechado',icon:'fechado.webp'},
  melou:{label:'Melou',icon:'melou.webp'},
  'falta-anunciar':{label:'Falta anunciar',icon:'falta-anunciar.webp'},
  'contrato-renovado':{label:'Contrato renovado',icon:'contrato-renovado.webp'}
};

function cffMercadoStatusKey(value){
  const raw=String(value||'rumor').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  const compact=raw.replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
  const aliases={
    'falta-anunciar':'falta-anunciar',
    'falta-de-anunciar':'falta-anunciar',
    'aguardando-anuncio':'falta-anunciar',
    'anunciar':'falta-anunciar',
    'contrato-renovado':'contrato-renovado',
    'renovado':'contrato-renovado',
    'renovacao':'contrato-renovado',
    'renovacao-de-contrato':'contrato-renovado',
    'contrato-renovacao':'contrato-renovado'
  };
  return aliases[compact]||compact||'rumor';
}

function cffMercadoStatusInfo(value){
  const key=cffMercadoStatusKey(value);
  return {key,...(CFF_MERCADO_STATUS_META[key]||{label:String(value||key||'Status'),icon:`${key}.webp`})};
}

window.cffMercadoStatusKey=cffMercadoStatusKey;
window.cffMercadoStatusInfo=cffMercadoStatusInfo;
window.CFF_MERCADO_STATUS_META=CFF_MERCADO_STATUS_META;

try{
  getMercadoStatusLabel=function(value){return cffMercadoStatusInfo(value).label};
}catch(_error){}

let cffMercadoCardsMounted=false;
let cffMercadoRenderVersion=0;

function cffMercadoSelectedTeam(){
  return document.getElementById('mercado-team-filter')?.value||'all';
}

function cffMercadoSameTeam(a,b){
  if(!a||!b)return false;
  if(typeof cffMercadoTeamMatches==='function')return cffMercadoTeamMatches(a,b);
  return String(a).trim().toUpperCase()===String(b).trim().toUpperCase();
}

function cffMercadoRowMatches(row){
  const statusOk=mercadoFilter==='all'||cffMercadoStatusKey(row.status)===mercadoFilter;
  const team=cffMercadoSelectedTeam();
  const teamOk=team==='all'||cffMercadoSameTeam(row.timeOrigem,team)||cffMercadoSameTeam(row.timeDestino,team);
  return statusOk&&teamOk;
}

function cffMercadoVoteId(player){
  return String(player||'').replace(/[\s.#$/[\]]/g,'_');
}

function cffMercadoUpdateVoteCard(card,row){
  const player=row.jogador;
  mercadoVotes[player]||(mercadoVotes[player]={up:0,down:0,voted:null});
  const vote=mercadoVotes[player];
  const total=Number(vote.up||0)+Number(vote.down||0);
  const percent=total?Math.round(Number(vote.up||0)/total*100):50;
  const up=card.querySelector('.vote-btn[data-vote="up"]');
  const down=card.querySelector('.vote-btn[data-vote="down"]');
  const bar=card.querySelector('.vote-bar-fill');
  const upCount=card.querySelector('[data-vote-count="up"]');
  const downCount=card.querySelector('[data-vote-count="down"]');
  up?.classList.toggle('voted-up',vote.voted==='up');
  down?.classList.toggle('voted-down',vote.voted==='down');
  if(bar)bar.style.width=`${percent}%`;
  if(upCount)upCount.textContent=vote.up>0?vote.up:'';
  if(downCount)downCount.textContent=vote.down>0?vote.down:'';
}

function cffMercadoBuildCard(row,index){
  const status=cffMercadoStatusInfo(row.status);
  const player=row.jogador;
  mercadoVotes[player]||(mercadoVotes[player]={up:0,down:0,voted:null});
  const vote=mercadoVotes[player];
  const total=Number(vote.up||0)+Number(vote.down||0);
  const percent=total?Math.round(Number(vote.up||0)/total*100):50;
  const avatars=renderMercadoAvatarStack(row,'full');
  const originLogo=resolveEscudo(row.escudoOrigem,row.timeOrigem);
  const isRenewed=status.key==='contrato-renovado';
  const hasOrigin=Boolean(row.timeOrigem&&String(row.timeOrigem).trim());
  const hasDestination=Boolean(row.timeDestino&&String(row.timeDestino).trim()&&row.timeDestino!=='?');
  const originName=hasOrigin?row.timeOrigem:(isRenewed&&hasDestination?row.timeDestino:'Sem Clube');
  const destinationName=isRenewed
    ? (hasDestination?row.timeDestino:originName)
    : (hasDestination?row.timeDestino:'Sem Clube');
  const destinationLogo=resolveEscudo(row.escudoDestino,isRenewed&&!hasDestination?originName:row.timeDestino);
  const originClick=resolveTeamClick(originName);
  const destinationClick=resolveTeamClick(destinationName);
  const originAttrs=originClick?`onclick="${originClick}" style="cursor:pointer;" title="Ver ${escapeMercadoHtml(originName)}"`:'';
  const destinationAttrs=destinationClick?`onclick="${destinationClick}" style="cursor:pointer;" title="Ver ${escapeMercadoHtml(destinationName)}"`:'';
  let arrowClass='arrow-white';
  if(!isRenewed)arrowClass=!hasOrigin&&hasDestination?'arrow-green':hasOrigin&&!hasDestination?'arrow-red':'arrow-white';
  const names=renderMercadoPlayerNames(row,'full');
  const safePlayer=escapeMercadoHtml(JSON.stringify(player));
  const voteId=cffMercadoVoteId(player);
  return `
    <div class="mercado-card status-${status.key}" data-status="${status.key}" data-market-index="${index}">
      ${avatars}
      <div class="mercado-card-status">
        <img class="mercado-status-icon" src="${status.icon}" onerror="this.style.display='none'" alt="${escapeMercadoHtml(status.label)}">
        <span class="mercado-status-label">${escapeMercadoHtml(status.label)}</span>
      </div>
      <div class="mercado-card-info">
        <div class="mercado-card-name">${names}</div>
        <div class="mercado-card-meta">
          ${row.role?`<span style="color:var(--accent);font-weight:800;font-size:.9em;text-transform:uppercase;">${escapeMercadoHtml(row.role)}</span><br>`:''}
          ${row.atualizacao?`Atualizado: <span>${escapeMercadoHtml(row.atualizacao)}</span>`:''}
        </div>
      </div>
      <div class="mercado-card-clubs">
        <div class="mercado-club" ${originAttrs}>
          <img src="${escapeMercadoHtml(originLogo)}" onerror="this.src='escudo.webp'" alt="${escapeMercadoHtml(originName)}">
          <span class="mercado-club-name">${escapeMercadoHtml(originName)}</span>
        </div>
        <img class="mercado-arrow ${arrowClass}" src="seta.webp" alt="→">
        <div class="mercado-club" ${destinationAttrs}>
          <img src="${escapeMercadoHtml(destinationLogo)}" onerror="this.src='escudo.webp'" alt="${escapeMercadoHtml(destinationName)}">
          <span class="mercado-club-name">${escapeMercadoHtml(destinationName)}</span>
        </div>
      </div>
      <div class="mercado-card-votes">
        <button class="vote-btn ${vote.voted==='up'?'voted-up':''}" data-vote="up" onclick="voteMercado(event, ${safePlayer}, 'up')">
          <span class="vote-icon">👍</span> <span id="vu-${voteId}" data-vote-count="up">${vote.up>0?vote.up:''}</span>
        </button>
        <div class="vote-bar-wrap"><div class="vote-bar-fill" id="vbar-${voteId}" style="width:${percent}%"></div></div>
        <button class="vote-btn ${vote.voted==='down'?'voted-down':''}" data-vote="down" onclick="voteMercado(event, ${safePlayer}, 'down')">
          <span class="vote-icon">👎</span> <span id="vd-${voteId}" data-vote-count="down">${vote.down>0?vote.down:''}</span>
        </button>
      </div>
    </div>`;
}

function cffMercadoMountCards(list){
  const cards=mercadoData.map(cffMercadoBuildCard).join('');
  list.innerHTML=`${cards}<div class="mercado-empty" id="mercado-filter-empty" hidden>Nenhuma negociação encontrada com estes filtros no momento.</div>`;
  list.dataset.marketVersion=String(cffMercadoRenderVersion);
  cffMercadoCardsMounted=true;
}

try{
  renderMercado=function(forceMount=false){
    const list=document.getElementById('mercado-list');
    if(!list)return;
    if(forceMount||!cffMercadoCardsMounted||list.dataset.marketVersion!==String(cffMercadoRenderVersion))cffMercadoMountCards(list);
    let visible=0;
    list.querySelectorAll('.mercado-card').forEach(card=>{
      const row=mercadoData[Number(card.dataset.marketIndex)];
      const show=Boolean(row&&cffMercadoRowMatches(row));
      card.hidden=!show;
      if(show)visible++;
      if(row)cffMercadoUpdateVoteCard(card,row);
    });
    const empty=document.getElementById('mercado-filter-empty');
    if(empty)empty.hidden=visible>0;
  };

  filterMercado=function(chip,status){
    mercadoFilter=status==='all'?'all':cffMercadoStatusKey(status);
    document.querySelectorAll('.mercado-filter-chip').forEach(item=>{
      item.classList.remove('active','active-rumor','active-negociando','active-fechado','active-melou','active-falta-anunciar','active-contrato-renovado');
      item.setAttribute('aria-pressed','false');
    });
    if(chip){
      chip.classList.add(mercadoFilter==='all'?'active':`active-${mercadoFilter}`);
      chip.setAttribute('aria-pressed','true');
    }
    window.requestAnimationFrame(()=>renderMercado(false));
  };

  renderHomeMercadoResumo=function(){
    const root=document.getElementById('home-mercado-list');
    if(!root)return;
    const rows=mercadoData.slice(0,5);
    if(!rows.length){root.innerHTML='<div class="home-mercado-empty">Nenhuma transferência cadastrada.</div>';return}
    root.innerHTML=rows.map(row=>{
      const status=cffMercadoStatusInfo(row.status);
      const avatar=renderMercadoAvatarStack(row,'home');
      const names=renderMercadoPlayerNames(row,'home');
      const origin=escapeMercadoHomeHtml(row.timeOrigem||'Sem Clube');
      const renewed=status.key==='contrato-renovado';
      const destination=escapeMercadoHomeHtml(renewed&&(!row.timeDestino||row.timeDestino==='?')?(row.timeOrigem||'Sem Clube'):(row.timeDestino&&row.timeDestino!=='?'?row.timeDestino:'Sem Clube'));
      const role=row.role?` · ${escapeMercadoHomeHtml(row.role)}`:'';
      return `<div class="home-mercado-mini-card" onclick="navigate('mercado')" title="Abrir Mercado da Bala">
        ${avatar}<div class="home-mercado-mini-main"><div class="home-mercado-mini-name">${names}${role}</div><div class="home-mercado-mini-route">${origin} → ${destination}</div></div>
        <div class="home-mercado-mini-status status-${status.key}"><img src="${status.icon}" onerror="this.style.display='none'" alt="${escapeMercadoHomeHtml(status.label)}"><span>${escapeMercadoHomeHtml(status.label)}</span></div>
      </div>`;
    }).join('');
  };

  const CFF_MERCADO_CACHE_KEY='cff_mercado_tsv_cache_v2';
  const CFF_MERCADO_CACHE_MAX_AGE=2*60*1000;

  function cffMercadoParseTsv(raw){
    const normalized=String(raw||'').replace(/^\uFEFF/,'').replace(/\r\n/g,'\n').replace(/\r/g,'\n').trim();
    if(!normalized)return[];
    const lines=normalized.split('\n').filter(line=>line.trim());
    return lines.slice(1).map(line=>{
      const cells=line.split('\t').map(cell=>cell.trim());
      const status=cffMercadoStatusKey(cells[2]||'rumor');
      return {jogador:cells[0]||'',foto:cells[1]||'',status,timeOrigem:cells[3]||'',escudoOrigem:cells[4]||'',timeDestino:cells[5]||'',escudoDestino:cells[6]||'',atualizacao:cells[7]||'',role:cells[8]||''};
    }).filter(row=>row.jogador);
  }

  function cffMercadoReadCache(){
    try{
      const cached=JSON.parse(localStorage.getItem(CFF_MERCADO_CACHE_KEY)||'null');
      if(!cached||!Array.isArray(cached.rows))return null;
      return cached;
    }catch(_error){return null}
  }

  function cffMercadoWriteCache(raw,rows){
    try{localStorage.setItem(CFF_MERCADO_CACHE_KEY,JSON.stringify({savedAt:Date.now(),raw,rows}))}catch(_error){}
  }

  function cffMercadoApplyRows(rows,{mount=true}={}){
    mercadoData=Array.isArray(rows)?rows:[];
    cffMercadoRenderVersion++;
    cffMercadoCardsMounted=false;
    if(typeof cffApplyMercadoDeparturesToCurrentPlayers==='function')cffApplyMercadoDeparturesToCurrentPlayers();
    const teams=new Set();
    mercadoData.forEach(row=>{
      if(row.timeOrigem&&row.timeOrigem!=='?'&&row.timeOrigem!=='Sem Clube')teams.add(row.timeOrigem);
      if(row.timeDestino&&row.timeDestino!=='?'&&row.timeDestino!=='Sem Clube')teams.add(row.timeDestino);
    });
    const select=document.getElementById('mercado-team-filter');
    if(select){
      const selected=select.value;
      select.innerHTML='<option value="all">Todas as Equipes</option>'+[...teams].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(team=>`<option value="${escapeMercadoHtml(team)}">${escapeMercadoHtml(team)}</option>`).join('');
      if([...select.options].some(option=>option.value===selected))select.value=selected;
    }
    mercadoHasLoaded=true;
    if(mount){
      renderMercado(true);
      renderHomeMercadoResumo();
      if(typeof window.fbLoadVotes==='function')window.fbLoadVotes();
    }
  }

  async function cffMercadoFetchSource(source){
    const controller=typeof AbortController==='function'?new AbortController():null;
    const timeout=controller?setTimeout(()=>controller.abort(),12000):null;
    try{
      const separator=source.includes('?')?'&':'?';
      const cacheWindow=Math.floor(Date.now()/120000);
      const response=await fetch(`${source}${separator}v=${cacheWindow}`,{cache:'default',signal:controller?.signal});
      if(!response.ok)throw new Error(`HTTP ${response.status}`);
      return await response.text();
    }finally{if(timeout)clearTimeout(timeout)}
  }

  loadMercado=function(options={}){
    const silent=Boolean(options&&options.silent);
    const skipPhotos=Boolean(options&&options.skipPhotos);
    const force=Boolean(options&&options.force);
    if(force){mercadoHasLoaded=false;mercadoLoadPromise=null;cffMercadoCardsMounted=false}
    if(mercadoHasLoaded){
      if(!silent){renderMercado(false);renderHomeMercadoResumo()}
      return Promise.resolve(mercadoData);
    }
    if(mercadoLoadPromise)return mercadoLoadPromise;

    mercadoLoadPromise=(async()=>{
      if(typeof window.cffLoadPlayerPhotoMap==='function')await window.cffLoadPlayerPhotoMap().catch(()=>null);
      const cached=cffMercadoReadCache();
      const cacheFresh=Boolean(cached&&Date.now()-Number(cached.savedAt||0)<CFF_MERCADO_CACHE_MAX_AGE);
      if(cached?.rows?.length&&!force)cffMercadoApplyRows(cached.rows,{mount:!silent});
      try{
        const source=String((typeof MERCADO_TSV_URL!=='undefined'&&MERCADO_TSV_URL)||window.CFF_CONFIG?.sheets?.mercado||'').trim();
        if(!source)throw new Error('Link da planilha do mercado não configurado');
        if(!cacheFresh||force){
          let raw;
          try{raw=await cffMercadoFetchSource(source)}catch(firstError){
            await new Promise(resolve=>setTimeout(resolve,900));
            raw=await cffMercadoFetchSource(source);
          }
          const rows=cffMercadoParseTsv(raw);
          if(!rows.length)throw new Error('Planilha do mercado sem linhas válidas');
          cffMercadoWriteCache(raw,rows);
          cffMercadoApplyRows(rows,{mount:!silent});
        }
        if(!skipPhotos&&typeof loadPhotos==='function'){
          Promise.resolve(loadPhotos()).then(()=>{
            cffMercadoCardsMounted=false;
            if(document.getElementById('mercado-list'))renderMercado(true);
            renderHomeMercadoResumo();
          }).catch(()=>{});
        }
        return mercadoData;
      }catch(error){
        if(cached?.rows?.length){
          cffMercadoApplyRows(cached.rows,{mount:!silent});
          console.warn('[Mercado] Usando cache local após falha da planilha:',error);
          return mercadoData;
        }
        const list=document.getElementById('mercado-list');
        if(list)list.innerHTML='<div class="mercado-empty">⚠️ Não foi possível carregar os dados.<br><small style="color:#777">A planilha será tentada novamente ao abrir o Mercado.</small></div>';
        const home=document.getElementById('home-mercado-list');
        if(home)home.innerHTML='<div class="home-mercado-empty">⚠️ Não foi possível carregar o mercado agora.</div>';
        console.error('[Mercado] Falha no carregamento:',error);
        throw error;
      }finally{mercadoLoadPromise=null}
    })();
    return mercadoLoadPromise;
  };
  window.loadMercado=loadMercado;

  function cffMercadoBoot(){
    if(!document.getElementById('home-mercado-list')&&!document.getElementById('mercado-list'))return;
    const run=()=>loadMercado({skipPhotos:true}).catch(()=>{});
    if(window.cffRunWhenIdle)window.cffRunWhenIdle(run,650);else setTimeout(run,650);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',cffMercadoBoot,{once:true});else cffMercadoBoot();

}catch(error){
  console.error('Falha ao aplicar atualização do Mercado da Bala:',error);
}
})();
